import{_ as s,o as a,c as n,ai as e}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"企业数字化：四大系统边界与问题全景","description":"","frontmatter":{},"headers":[],"relativePath":"scenarios/enterprise-digital/index.md","filePath":"scenarios/enterprise-digital/index.md"}'),r={name:"scenarios/enterprise-digital/index.md"};function i(o,t,p,d,l,h){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="企业数字化-四大系统边界与问题全景" tabindex="-1">企业数字化：四大系统边界与问题全景 <a class="header-anchor" href="#企业数字化-四大系统边界与问题全景" aria-label="Permalink to “企业数字化：四大系统边界与问题全景”">​</a></h1><blockquote><p><strong>一句话定位</strong>：企业数字化不是&quot;上四套系统&quot;，而是让同一个物料在 ERP、WMS、MES、IIoT 里始终只有<strong>一个真相</strong>——该做什么、做得怎样、东西在哪、设备在干什么。</p><p><strong>本文用途</strong>：面试前 20 分钟速览。先分清四层边界，再按清单逐条自查。四篇分册见 <a href="/my-vitepress-site/scenarios/enterprise-digital/erp.html">ERP</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/wms.html">WMS</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/mes.html">MES</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/iiot.html">IIoT</a>。</p></blockquote><h2 id="一、四层边界-四个判据分清归属" tabindex="-1">一、四层边界：四个判据分清归属 <a class="header-anchor" href="#一、四层边界-四个判据分清归属" aria-label="Permalink to “一、四层边界：四个判据分清归属”">​</a></h2><p>面试被问&quot;ERP 和 MES 什么区别&quot;，不要背定义，直接给判据。</p><table tabindex="0"><thead><tr><th>判据</th><th>归属</th><th>说明</th></tr></thead><tbody><tr><td>要不要<strong>记账</strong>、算钱</td><td>ERP</td><td>订单、应收应付、成本、总账</td></tr><tr><td>要不要<strong>动位置</strong></td><td>WMS</td><td>库位、容器、上下架、拣货路径</td></tr><tr><td>要不要管<strong>工序和人</strong></td><td>MES</td><td>工单、工序流转、报工、质检</td></tr><tr><td>要不要<strong>直连设备</strong></td><td>IIoT</td><td>协议、点位、采集、设备状态</td></tr></tbody></table><p>四层各自的时间粒度也是天然的划分依据：</p><table tabindex="0"><thead><tr><th>层</th><th>回答的问题</th><th>管理对象</th><th>时间粒度</th><th>典型角色</th></tr></thead><tbody><tr><td>ERP</td><td>该做什么、值多少钱</td><td>订单 / 物料 / 资金</td><td>天 · 周 · 月</td><td>计划员、财务</td></tr><tr><td>MES</td><td>现在做得怎么样</td><td>工单 / 工序 / 人机料法环</td><td>分钟 · 小时</td><td>车间主管、班组长</td></tr><tr><td>WMS</td><td>东西在哪、怎么动</td><td>库位 / 批次 / 容器</td><td>秒 · 分钟</td><td>仓管、拣货员</td></tr><tr><td>IIoT</td><td>设备在干什么</td><td>点位 / 设备 / 状态</td><td>毫秒 · 秒</td><td>设备工程师</td></tr></tbody></table><blockquote><p><strong>面试口径</strong>：ERP 是&quot;账本&quot;，WMS 是&quot;地图&quot;，MES 是&quot;工位看板&quot;，IIoT 是&quot;神经末梢&quot;。四者不是替代关系，是四个时间尺度上的同一件事。</p></blockquote><h2 id="二、主链路-一条线串起四个系统" tabindex="-1">二、主链路：一条线串起四个系统 <a class="header-anchor" href="#二、主链路-一条线串起四个系统" aria-label="Permalink to “二、主链路：一条线串起四个系统”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>客户订单</span></span>
<span class="line"><span>   │  ERP：销售订单 → MRP 运算 → 采购申请 / 生产工单</span></span>
<span class="line"><span>   ├──────────────────────────────┬──────────────────────┐</span></span>
<span class="line"><span>   ▼                              ▼                      ▼</span></span>
<span class="line"><span>采购到货                        生产工单                设备侧</span></span>
<span class="line"><span>   │                              │                      │</span></span>
<span class="line"><span>   ▼                              ▼                      ▼</span></span>
<span class="line"><span>WMS：收货 → 质检 → 上架      MES：派工 → 报工 → 质检   IIoT：采集产量/状态/参数</span></span>
<span class="line"><span>   │                              │                      │</span></span>
<span class="line"><span>   └──────────► 库存 ────────────┘                      │</span></span>
<span class="line"><span>                  │                                     │</span></span>
<span class="line"><span>                  ▼                                     │</span></span>
<span class="line"><span>            WMS：波次拣货 → 复核 → 发运                  │</span></span>
<span class="line"><span>                  │                                     │</span></span>
<span class="line"><span>                  ▼                                     │</span></span>
<span class="line"><span>            ERP：应收 / 应付 → 成本核算 → 总账  ◄────────┘</span></span>
<span class="line"><span>                                        （实际产量、能耗、工时回写）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>链路里有两个容易讲错的地方，面试常用来区分&quot;用过系统&quot;和&quot;懂系统&quot;：</p><ol><li><strong>成品入库谁发起</strong>：MES 完工报工发起入库申请，WMS 执行实物上架，ERP 只接收&quot;库存增加&quot;的账务结果——三件事、三个系统、三种语义。</li><li><strong>实际成本从哪来</strong>：材料成本来自 WMS 的实际领料（不是 BOM 标准用量），人工与制造费用来自 MES 的报工工时和设备运行数据，ERP 只做归集与分摊。</li></ol><h2 id="三、跨系统的四道坎" tabindex="-1">三、跨系统的四道坎 <a class="header-anchor" href="#三、跨系统的四道坎" aria-label="Permalink to “三、跨系统的四道坎”">​</a></h2><p>这四道坎是所有工业软件项目的公共难点，也是面试里&quot;能不能做架构&quot;的试金石。</p><h3 id="坎-1-主数据不统一" tabindex="-1">坎 1：主数据不统一 <a class="header-anchor" href="#坎-1-主数据不统一" aria-label="Permalink to “坎 1：主数据不统一”">​</a></h3><p><strong>问题</strong>：同一个物料，ERP 叫 <code>M-001</code>，MES 叫 <code>物料A</code>，WMS 叫 <code>SKU0001</code>；单位一个用&quot;个&quot;一个用&quot;箱&quot;。集成一上线，第一条数据就错。</p><p><strong>解法</strong>：确立<strong>主数据单一权威源</strong>（通常是 ERP 或独立 MDM），其余系统只做映射不做新增。物料编码全局唯一、单位建换算表、工厂/仓库/库位统一编码规则。接口传输时<strong>只传编码不传名称</strong>。</p><p><strong>面试口径</strong>：集成的第一件事不是写接口，是坐下来定编码规则。主数据没统一，接口写得再漂亮都是在同步错误。</p><h3 id="坎-2-库存谁是唯一真相" tabindex="-1">坎 2：库存谁是唯一真相 <a class="header-anchor" href="#坎-2-库存谁是唯一真相" aria-label="Permalink to “坎 2：库存谁是唯一真相”">​</a></h3><p><strong>问题</strong>：ERP 有库存、WMS 也有库存，两边差 37 件，谁的准？谁也不认。</p><p><strong>解法</strong>：<strong>实物以 WMS 为准，账面以 ERP 为准</strong>，WMS 每次库存变动实时（或准实时）推送 ERP；ERP 不允许手工改库存，只能通过单据调整；每日做库存对账任务，差异进异常池人工处理。</p><p><strong>面试口径</strong>：一个物料在一个时点只能有一个权威库存。两个系统都能改库存，等于没有库存。</p><h3 id="坎-3-单据状态对不齐" tabindex="-1">坎 3：单据状态对不齐 <a class="header-anchor" href="#坎-3-单据状态对不齐" aria-label="Permalink to “坎 3：单据状态对不齐”">​</a></h3><p><strong>问题</strong>：ERP 里工单已&quot;完工&quot;，MES 里还在&quot;生产中&quot;；ERP 已&quot;关闭&quot;，WMS 还有未清的领料单。</p><p><strong>解法</strong>：定义<strong>跨系统状态映射表</strong>，只允许单向驱动（下游不能反向改上游终态）；每个单据带全局唯一业务号和版本号；状态回写走事件而非轮询。</p><p><strong>面试口径</strong>：状态机对齐的关键是&quot;谁有权推进状态&quot;写清楚。多个系统都能推同一个状态，必然打架。</p><h3 id="坎-4-一致性只有最终一致" tabindex="-1">坎 4：一致性只有最终一致 <a class="header-anchor" href="#坎-4-一致性只有最终一致" aria-label="Permalink to “坎 4：一致性只有最终一致”">​</a></h3><p><strong>问题</strong>：ERP 扣了库存，WMS 上架失败，中间件超时，数据悬空。</p><p><strong>解法</strong>：本地事务 + 消息表（Transactional Outbox）+ 消费端幂等 + 定时对账兜底。不做跨系统强一致，做<strong>可补偿的最终一致</strong>：每笔跨系统操作留&quot;业务流水 + 状态 + 重试次数&quot;，卡住就告警。</p><p><strong>面试口径</strong>：跨系统不要谈分布式事务，谈&quot;本地消息表 + 幂等 + 对账&quot;。前两个保证不丢不重，第三个保证错了能发现。</p><h2 id="四、四套系统的核心问题索引" tabindex="-1">四、四套系统的核心问题索引 <a class="header-anchor" href="#四、四套系统的核心问题索引" aria-label="Permalink to “四、四套系统的核心问题索引”">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>核心命题</th><th>最硬的三个问题</th><th>分册</th></tr></thead><tbody><tr><td>ERP</td><td>计划准不准、成本算不算得清</td><td>MRP 运算、BOM 变更、成本核算</td><td><a href="/my-vitepress-site/scenarios/enterprise-digital/erp.html">ERP 核心问题</a></td></tr><tr><td>WMS</td><td>库存准不准、作业快不快</td><td>库存准确性、波次拣货、批次效期</td><td><a href="/my-vitepress-site/scenarios/enterprise-digital/wms.html">WMS 核心问题</a></td></tr><tr><td>MES</td><td>工单跑不跑得通、追溯追不追得到</td><td>工单状态机、报工与倒冲、质量追溯</td><td><a href="/my-vitepress-site/scenarios/enterprise-digital/mes.html">MES 核心问题</a></td></tr><tr><td>IIoT</td><td>数据采不采得上、存不存得住</td><td>协议碎片化、断线不丢数、时序存储</td><td><a href="/my-vitepress-site/scenarios/enterprise-digital/iiot.html">IIoT 核心问题</a></td></tr></tbody></table><h2 id="五、60-秒自测-能不能讲清一条链路" tabindex="-1">五、60 秒自测：能不能讲清一条链路 <a class="header-anchor" href="#五、60-秒自测-能不能讲清一条链路" aria-label="Permalink to “五、60 秒自测：能不能讲清一条链路”">​</a></h2><p>面试官问&quot;你做过库存，讲一下从采购到入库怎么走&quot;，合格的回答应该包含<strong>四层各一句</strong>：</p><blockquote><p>采购单在 ERP 下达并审核，生成到货通知推给 WMS；WMS 按 ASN 预约月台收货，扫批次号入库到质检区，质检合格后按上架策略分配库位，实物上架同时把&quot;库存增加&quot;回写 ERP；ERP 收到回写后更新账面库存和暂估应付，等发票到了做三单匹配生成应付。整个链路里 WMS 管实物位置和批次，ERP 管账和钱，中间用业务单号做幂等，每天跑一次库存对账兜底。</p></blockquote><p>这段话里藏了 6 个技术点：主数据、状态映射、幂等键、实物与账面分离、暂估应付、对账补偿。能把它们逐个展开，追问就接得住了。</p><hr><p>上一级：<a href="/my-vitepress-site/scenarios/">解决方案总览</a></p>`,38)])])}const g=s(r,[["render",i]]);export{b as __pageData,g as default};
